INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $pilot$PT128-S3-Q16$pilot$, 128, 3, 16, $pilot$Main Conclusion$pilot$, $pilot$The primary task of a university is to educate. But to teach well, professors must be informed about new developments in their disciplines, and that requires research. Yet many universities cannot afford to support faculty research adequately. So a lack of funds for research adversely affects the degree to which a university can fulfill its central mission.$pilot$, $pilot$Which one of the following most accurately expresses the conclusion of the argument?$pilot$, $pilot$D$pilot$, true, $pilot$Pilot approved 2026-09-28; question text from local bank snapshot.$pilot$ FROM lr_sections s WHERE s.preptest=128 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$pilot$PT128-S3-Q16$pilot$) ON CONFLICT DO NOTHING;
